-- Sample learning catalogue content for development and evaluation. No instructors are attributed.
ALTER TABLE courses ADD COLUMN prerequisites TEXT;
INSERT INTO categories(name, description) SELECT 'Programming','Programming languages, software design and algorithms' WHERE NOT EXISTS (SELECT 1 FROM categories WHERE name='Programming');
INSERT INTO categories(name, description) SELECT 'Data Science & AI','Data analysis, machine learning and artificial intelligence' WHERE NOT EXISTS (SELECT 1 FROM categories WHERE name='Data Science & AI');
INSERT INTO categories(name, description) SELECT 'Professional Skills','Practical skills for modern professional work' WHERE NOT EXISTS (SELECT 1 FROM categories WHERE name='Professional Skills');
INSERT INTO categories(name, description) SELECT 'Cloud & DevOps','Cloud platforms, infrastructure and DevOps practices.' WHERE NOT EXISTS (SELECT 1 FROM categories WHERE name='Cloud & DevOps');

INSERT INTO courses(title, short_description, description, category_id, difficulty, duration_minutes, thumbnail_path, learning_outcomes, prerequisites, published)
SELECT s.title, replace(s.outcomes, '|', ' · '), 'Sample learning content for independent study. ' || s.title || ' introduces ' || replace(s.outcomes, '|', ', ') || '. Includes guided examples, practice and a small applied exercise.', c.id, s.difficulty, s.duration::integer, 'seed:' || s.cover, s.outcomes,
 CASE s.difficulty WHEN 'BEGINNER' THEN 'No prior experience is required.' WHEN 'INTERMEDIATE' THEN 'Basic programming or subject familiarity is recommended.' ELSE 'Comfort with foundational concepts in this subject is recommended.' END, TRUE
FROM (VALUES
 ('Java Programming Masterclass', 'Programming', 'BEGINNER', '360', 'Java syntax and types|Object-oriented design|Collections and exceptions', 'code.svg'),
 ('Python for Beginners to Advanced', 'Programming', 'BEGINNER', '420', 'Python control flow|Reusable functions and modules|File and data handling', 'python.svg'),
 ('C Programming Fundamentals', 'Programming', 'BEGINNER', '300', 'C functions and types|Arrays and pointers|Compile and debug programs', 'code.svg'),
 ('C++ Programming', 'Programming', 'INTERMEDIATE', '360', 'Modern C++ syntax|Classes and resource management|Standard library containers', 'code.svg'),
 ('Data Structures and Algorithms', 'Programming', 'INTERMEDIATE', '420', 'Big-O analysis|Core data structures|Search and sorting techniques', 'code.svg'),
 ('Object-Oriented Programming', 'Programming', 'BEGINNER', '240', 'Encapsulation and composition|Interfaces and polymorphism|Readable object models', 'java.svg'),
 ('HTML and CSS Complete Course', 'Web Development', 'BEGINNER', '300', 'Semantic HTML|Responsive Flexbox and Grid|Accessible page styling', 'design.svg'),
 ('JavaScript Modern Development', 'Web Development', 'BEGINNER', '360', 'Modern JavaScript syntax|Promises and async workflows|Browser interactions', 'code.svg'),
 ('Full Stack Java Development', 'Web Development', 'INTERMEDIATE', '480', 'Layered application design|REST integration and validation|Relational data persistence', 'java.svg'),
 ('Node.js Backend Development', 'Web Development', 'INTERMEDIATE', '360', 'Node modules and runtime|REST routes and middleware|Async data services', 'code.svg'),
 ('MySQL Database Development', 'Databases', 'BEGINNER', '300', 'Relational schema design|SQL joins and aggregates|Indexes and constraints', 'database.svg'),
 ('SQL for Data Analytics', 'Databases', 'INTERMEDIATE', '240', 'Analytical joins and aggregates|Window functions|Readable data queries', 'analytics.svg'),
 ('Database Design and Optimization', 'Databases', 'ADVANCED', '300', 'Normalization and constraints|Index strategy|Explain query plans', 'database.svg'),
 ('Python for Data Science', 'Data Science & AI', 'BEGINNER', '360', 'Tabular data analysis|Descriptive statistics|Communicate analytical findings', 'analytics.svg'),
 ('Machine Learning Fundamentals', 'Data Science & AI', 'INTERMEDIATE', '420', 'Prepare model features|Train baseline models|Evaluate model performance', 'ai.svg'),
 ('Artificial Intelligence Fundamentals', 'Data Science & AI', 'BEGINNER', '240', 'Search and reasoning approaches|Machine learning concepts|Evaluation and responsible use', 'ai.svg'),
 ('Deep Learning', 'Data Science & AI', 'ADVANCED', '420', 'Neural network components|Training and validation|Regularization concepts', 'ai.svg'),
 ('Data Analytics with Python', 'Data Science & AI', 'INTERMEDIATE', '300', 'Clean and combine data|Create visual summaries|Structure repeatable analysis', 'analytics.svg'),
 ('Power BI Professional Course', 'Data Science & AI', 'INTERMEDIATE', '360', 'Prepare data models|Create measures|Design navigable reports', 'analytics.svg'),
 ('AWS Cloud Practitioner', 'Cloud & DevOps', 'BEGINNER', '300', 'Cloud shared responsibility|Core infrastructure concepts|Cost and security basics', 'cloud.svg'),
 ('Docker and Kubernetes', 'Cloud & DevOps', 'INTERMEDIATE', '420', 'Build Docker images|Configure container services|Understand Kubernetes workloads', 'devops.svg'),
 ('Git and GitHub', 'Cloud & DevOps', 'BEGINNER', '180', 'Commit and branch effectively|Resolve merge conflicts|Collaborate with pull requests', 'devops.svg'),
 ('CI/CD and DevOps Fundamentals', 'Cloud & DevOps', 'INTERMEDIATE', '300', 'Pipeline stages and checks|Automated delivery concepts|Release and rollback planning', 'devops.svg'),
 ('UI/UX Design', 'Web Development', 'BEGINNER', '300', 'Map user goals|Structure interface information|Review usability and accessibility', 'design.svg'),
 ('Software Testing and Automation', 'Programming', 'INTERMEDIATE', '360', 'Choose testing levels|Write reliable test cases|Automate repeatable checks', 'testing.svg'),
 ('Cybersecurity Fundamentals', 'Cloud & DevOps', 'BEGINNER', '300', 'Model common threats|Apply access control|Understand defensive response', 'security.svg'),
 ('Excel for Data Analysis', 'Data Science & AI', 'BEGINNER', '180', 'Clean tabular data|Use formulas and lookups|Summarize with pivots and charts', 'analytics.svg'),
 ('Business Communication', 'Professional Skills', 'BEGINNER', '150', 'Adapt messages to the audience|Write concise workplace content|Give constructive feedback', 'communication.svg')
) AS s(title, category_name, difficulty, duration, outcomes, cover)
JOIN categories c ON c.name=s.category_name
WHERE NOT EXISTS (SELECT 1 FROM courses old WHERE lower(old.title)=lower(s.title));

