UPDATE courses SET thumbnail_path='seed:java.svg' WHERE title='Spring Boot REST APIs in Practice' AND thumbnail_path IS NULL;
UPDATE courses SET thumbnail_path='seed:design.svg' WHERE title='React Fundamentals' AND thumbnail_path IS NULL;
UPDATE courses SET thumbnail_path='seed:database.svg' WHERE title='PostgreSQL Design and Queries' AND thumbnail_path IS NULL;
